#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#elif defined(__AVX__)
#define VW 8
#define MR 6
#else
#define VW 4
#define MR 6
#endif
#define NR (2 * VW)
#define KC 256
#define MCP (96 / MR)          /* row panels per task */
#define JCP (64 / NR)          /* col panels per task */

typedef float vf  __attribute__((vector_size(VW * 4), aligned(VW * 4)));
typedef float vfu __attribute__((vector_size(VW * 4), aligned(4)));

static float *g_buf = NULL;
static size_t g_cap = 0;

static inline __attribute__((always_inline))
void kern(int kc, const float *restrict a, const float *restrict b,
          float *restrict c, int ldc, int acc)
{
    vf c0[MR], c1[MR];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) { c0[i] = (vf){0}; c1[i] = (vf){0}; }
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float s = a[i];
            c0[i] += s * b0;
            c1[i] += s * b1;
        }
        a += MR;
        b += NR;
    }
    if (acc) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += c0[i];
            *(vfu *)(c + i * ldc + VW) += c1[i];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = c0[i];
            *(vfu *)(c + i * ldc + VW) = c1[i];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    const int mp = (n + MR - 1) / MR;      /* row panels of A */
    const int np = (n + NR - 1) / NR;      /* col panels of B */
    size_t asz = (size_t)mp * MR * n;
    size_t bsz = (size_t)np * NR * n;
    size_t need = asz + bsz + 64;
    if (need > g_cap) {
        free(g_buf);
        g_buf = (float *)aligned_alloc(64, ((need * sizeof(float)) + 63) & ~(size_t)63);
        g_cap = need;
    }
    float *Ap = g_buf;
    float *Bp = g_buf + ((asz + 15) & ~(size_t)15);

    const int nti = (mp + MCP - 1) / MCP;
    const int ntj = (np + JCP - 1) / JCP;

#pragma omp parallel
    {
        /* cooperative packing of all A row panels and B col panels */
#pragma omp for schedule(dynamic, 2)
        for (int t = 0; t < mp + np; t++) {
            if (t < mp) {
                int i0 = t * MR;
                float *dst = Ap + (size_t)t * MR * n;
                for (int r = 0; r < MR; r++) {
                    int i = i0 + r;
                    if (i < n) {
                        const float *src = A + (size_t)i * n;
                        for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = src[k];
                    } else {
                        for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = 0.0f;
                    }
                }
            } else {
                int jp = t - mp;
                int j0 = jp * NR;
                int w = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)jp * NR * n;
                for (int k = 0; k < n; k++) {
                    const float *src = B + (size_t)k * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (w == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        for (int j = 0; j < w; j++) d[j] = src[j];
                        for (int j = w; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        /* compute: fine-grained dynamic tasks, each loops over all K blocks */
#pragma omp for collapse(2) schedule(dynamic, 1)
        for (int ti = 0; ti < nti; ti++) {
            for (int tj = 0; tj < ntj; tj++) {
                int ip0 = ti * MCP, ip1 = ip0 + MCP < mp ? ip0 + MCP : mp;
                int jp0 = tj * JCP, jp1 = jp0 + JCP < np ? jp0 + JCP : np;
                float tmp[MR * NR] __attribute__((aligned(64)));
                for (int k0 = 0; k0 < n; k0 += KC) {
                    int kc = n - k0 < KC ? n - k0 : KC;
                    int acc = k0 > 0;
                    for (int jp = jp0; jp < jp1; jp++) {
                        const float *bp = Bp + (size_t)jp * NR * n + (size_t)k0 * NR;
                        int j0 = jp * NR;
                        int w = n - j0 < NR ? n - j0 : NR;
                        for (int ip = ip0; ip < ip1; ip++) {
                            const float *ap = Ap + (size_t)ip * MR * n + (size_t)k0 * MR;
                            int i0 = ip * MR;
                            int h = n - i0 < MR ? n - i0 : MR;
                            if (h == MR && w == NR) {
                                kern(kc, ap, bp, C + (size_t)i0 * n + j0, n, acc);
                            } else {
                                kern(kc, ap, bp, tmp, NR, 0);
                                for (int i = 0; i < h; i++) {
                                    float *cr = C + (size_t)(i0 + i) * n + j0;
                                    const float *tr = tmp + i * NR;
                                    if (acc) for (int j = 0; j < w; j++) cr[j] += tr[j];
                                    else     for (int j = 0; j < w; j++) cr[j] = tr[j];
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
